"""Сценарные ответы модели для создания новой книги: орбитальная станция вместо мира оригинала."""
import re

NAMES = ["Вера Лунина", "Осип Градов", "Дина Ракитина", "Борис Кассель", "Ника Фрей", "Егор Мальцев", "Алиса Вершинина", "Роман Штерн"]
SCENES = [
    "Инженер замечает сбой в шлюзе и решает не сообщать экипажу, пока не поймёт причину",
    "Связист получает обрывок передачи на частоте, которой не должно быть, и прячет запись",
    "Капитан созывает совет, где обнаруживается, что журнал дежурств переписан чужой рукой",
    "Врач находит в медотсеке пустую капсулу и понимает, что станция не одна",
    "Экипаж спорит о запасах кислорода, а пилот тайком готовит спасательный модуль",
    "В техническом отсеке находят схему станции с отметками, которые никто не делал",
    "Ночной дежурный слышит шаги в закрытом секторе и идёт проверить в одиночку",
    "Хранитель архива открывает файл, который стирал сам много лет назад",
    "Тревога на станции заставляет всех собраться в одном зале, где и раскрывается обман",
    "Последний выход в открытый космос решает судьбу станции и тех, кто на ней остался",
    "Расшифрованная передача указывает на источник сигнала, и экипаж принимает решение",
]


def premise() -> dict:
    return {"title": "Тишина на орбите", "logline": "Экипаж забытой орбитальной станции раскрывает, кто переписывает её журнал.",
            "genre": "космическая фантастика", "setting": "Орбитальная станция на окраине обжитого космоса, двадцать второй век.",
            "tone": "тревожный, камерный", "central_conflict": "Экипаж не доверяет друг другу, пока ресурсы станции на исходе.",
            "themes": ["доверие", "изоляция"], "world_rules": ["Связь с Землёй задерживается на сутки", "Кислород расходуется строго по нормам"]}


def cast(prompt: str) -> dict:
    roles = re.findall(r"^- ([^(\n]+?)(?: \(арка:.*)?$", prompt.split("РОЛИ")[1].split("ОБЯЗАТЕЛЬНЫЕ")[0], re.MULTILINE)
    members = []
    for i, role in enumerate(r.strip() for r in roles if r.strip()):
        members.append({"role": role, "name": NAMES[i % len(NAMES)], "appearance": "худой, внимательный взгляд",
                        "personality": "сдержанный", "goal": f"добиться своего ({role})", "weakness": "усталость", "secret": "скрывает старую ошибку",
                        "backstory": "служит на станции пятый год"})
    return {"members": members}


def chapter(prompt: str) -> dict:
    n = int(re.search(r"план главы (\d+) из", prompt).group(1))
    heroes = re.findall(r"^- ([^()\n]+?) \(", prompt.split("ГЕРОИ:")[1].split("ЧТО УЖЕ ПРОИЗОШЛО")[0], re.MULTILINE)
    section = prompt.split("БИТЫ ЭТОЙ ГЛАВЫ")[1].split("БЛИЖАЙШИЕ БИТЫ")[0]
    beats = re.findall(r"^\[(B\d+)\]", section, re.MULTILINE)
    pov = heroes[(n - 1) % len(heroes)]
    other = heroes[n % len(heroes)]
    return {"title": f"Отсек {n}", "summary": f"{SCENES[(n - 1) % len(SCENES)]}. {pov} и {other} вынуждены действовать вместе.",
            "pov": pov, "location": f"сектор {n}", "goal": "разобраться в происходящем", "conflict": "нехватка времени и доверия",
            "outcome": "картина становится сложнее", "characters": [pov, other], "relationship_changes": [f"{pov} и {other} сближаются"],
            "clues_planted": [f"деталь номер {n}"] if beats else [], "reveals": [], "hook": "в динамиках раздаётся чужой голос",
            "beats_covered": beats}


def prose(prompt: str) -> str:
    """Подставной текст части главы: нужной длины, без имён оригинала, абзацы не повторяются."""
    words = int(re.search(r"примерно (\d+) слов", prompt).group(1))
    part = int(re.search(r"часть (\d+) из", prompt).group(1))
    number = int(re.search(r"главы (\d+) «", prompt).group(1))
    heroes = re.findall(r"^- ([^()\n]+?) \(", prompt.split("ГЕРОИ")[1].split("ЧТО БЫЛО")[0], re.MULTILINE)
    out, n, k = [], 0, 0
    while n < words * 1.1:
        h = heroes[(number + k) % len(heroes)]
        para = (f"{h} остановился в секторе {number}, часть {part}, абзац {k + 1}, и прислушался к гулу станции. "
                f"Кислорода оставалось на {10 + k} суток, а ответов не прибавлялось, и каждый шаг по коридору отдавался в висках. "
                f"— Мы не можем ждать, — сказал {h} и впервые за долгое время не отвёл взгляда.")
        out.append(para)
        n += len(para.split())
        k += 1
    return "\n\n".join(out)
